export const BODY: string = "\n<p>جس تصویر کا پس منظر ہٹا دیا گیا ہو وہ صرف آدھی تیار ہوتی ہے۔ شفاف کٹ آؤٹ کو استعمال سے پہلے پیچھے کچھ چاہیے ہوتا ہے، اور سادہ تصویر کو بھی اکثر نیا پس منظر چاہیے ہوتا ہے۔</p>\n<p>Add Background to Image ٹول کسی بھی تصویر یا شفاف PNG کو ٹھوس رنگ، دو رنگوں والے گریڈینٹ، یا خود اسی کی دھندلی کاپی پر رکھ دیتا ہے۔ یہ مکمل طور پر آپ کے براؤزر میں چلتا ہے۔</p>\n<p>اس گائیڈ میں تینوں پس منظر موڈ، فریمنگ کنٹرول اور ایکسپورٹ آپشن بتائے گئے ہیں، اور دکھایا گیا ہے کہ ہر انتخاب کب درست ہوتا ہے۔ چاہے آپ مصنوعات بیچتے ہوں یا سوشل پوسٹ بناتے ہوں، یہ گائیڈ کام آئے گی۔</p>\n<h2 id=\"what-adding-a-background-means\">پس منظر شامل کرنے کا مطلب کیا ہے</h2>\n<p>پس منظر شامل کرنے کا مطلب ہے کہ سامنے والی تصویر کو نئے پس منظر پر رکھا جائے۔ سامنے والی تصویر شفاف PNG کٹ آؤٹ، پروڈکٹ فوٹو، لوگو یا اسکرین شاٹ ہو سکتی ہے۔</p>\n<p>نتیجہ ایک تیار تصویر ہوتی ہے جس میں سامنے والی تصویر اور پس منظر ایک ساتھ جڑے ہوتے ہیں۔ اسے JPG یا PNG کے طور پر محفوظ کیا جا سکتا ہے اور ہر جگہ استعمال کیا جا سکتا ہے جہاں عام تصویر چلتی ہے۔</p>\n<p>یہ پس منظر ہٹانے سے مختلف ہے، جو کچھ لے جاتا ہے۔ پس منظر شامل کرنا وہ منظر بناتا ہے جس میں سامنے والی تصویر بیٹھتی ہے۔ دونوں مرحلے اکثر ساتھ کام کرتے ہیں۔</p>\n<p>یہ ٹول خود پس منظر نہیں ہٹاتا۔ اگر آپ کی تصویر میں ابھی بھی اصل پس منظر موجود ہے تو پہلے بیک گراؤنڈ ریموول ایپ سے شفاف کٹ آؤٹ بنائیں۔</p>\n<h2 id=\"the-three-background-modes\">تین پس منظر موڈ</h2>\n<p>Solid Color موڈ کینوس کو ایک فلیٹ رنگ سے بھر دیتا ہے۔ یہ پروڈکٹ فوٹو، لوگو اور ایپ اسکرین شاٹس کے لیے صاف ترین انتخاب ہے، کیونکہ کچھ بھی سامنے والی تصویر سے مقابلہ نہیں کرتا۔</p>\n<p>Gradient موڈ آپ کے چنے ہوئے زاویے پر دو رنگوں کو کینوس پر ملاتا ہے۔ یہ بغیر بے ترتیبی کے گہرائی بڑھاتا ہے، جو سوشل پوسٹس، اسٹوری فریم اور پروموشن کے لیے موزوں ہے۔</p>\n<p>Blurred Photo موڈ کینوس کو سامنے والی تصویر کی ہی دھندلی کاپی سے بھر دیتا ہے۔ یہ اس تصویر کا کلاسک حل ہے جو فریم کی شکل سے میل نہیں کھاتی: خالی جگہ اپنی ہی دھندلی شکل سے بھر جاتی ہے۔</p>\n<p>ہر موڈ کے اپنے کنٹرول ہیں۔ Solid Color میں فوری سوئچ اور اپنی مرضی کا پکر ملتا ہے، Gradient میں دو رنگ اور زاویہ ملتا ہے، اور Blurred Photo میں بلر کی شدت ملتی ہے۔</p>\n<h2 id=\"solid-color-backgrounds\">ٹھوس رنگ والے پس منظر</h2>\n<p>ٹھوس پس منظر سب سے محفوظ انتخاب ہے جب سامنے والی تصویر ہی واحد چیز ہو جسے آنکھ دیکھے۔ پروڈکٹ لسٹنگ، پروفائل تصویر اور لوگو شیٹ سب اس سے فائدہ اٹھاتے ہیں۔</p>\n<p>سفید ای کامرس کا ڈیفالٹ ہے کیونکہ مارکیٹ پلیس اس کی توقع رکھتے ہیں اور کیونکہ اس سے مصنوعات صاف اور ایماندار لگتی ہیں۔ سفید پس منظر پرنٹ میں بھی اچھا لگتا ہے۔</p>\n<p>برانڈ رنگ تب کام کرتے ہیں جب تصویر لسٹنگ کے بجائے مہم کا حصہ ہو۔ برانڈ رنگ والے مربع پر کٹ آؤٹ ڈیزائن شدہ گرافک لگتا ہے، اور ان کا سیٹ ایک پیشہ ورانہ سیریز بناتا ہے۔</p>\n<p>گہرے پس منظر پریمیم مصنوعات اور ڈرامائی تصاویر کے لیے موزوں ہیں۔ گہرا پس منظر ہلکی مصنوعات کو چمکاتا ہے اور تصویر کو اسٹوڈیو کا احساس دیتا ہے۔ مگر کناروں پر نظر رکھیں۔</p>\n<h2 id=\"gradient-backgrounds\">گریڈینٹ پس منظر</h2>\n<p>گریڈینٹ ایک رنگ سے دوسرے رنگ تک کینوس پر چلتا ہے، اور زاویہ کنٹرول ملاوٹ کی سمت طے کرتا ہے۔ ترچھا گریڈینٹ متحرک لگتا ہے، عمودی گریڈینٹ پرسکون لگتا ہے۔</p>\n<p>گریڈینٹ تب بہترین کام کرتے ہیں جب دونوں رنگ قریبی رشتہ دار ہوں، جیسے دو نیلے یا نیلا اور فیروزی۔ قریبی رنگ ہمواری سے ملتے ہیں اور جان بوجھ کر لگتے ہیں۔</p>\n<p>سوشل گرافکس گریڈینٹ کا قدرتی گھر ہیں۔ اسٹوری فریم، اقتباس کارڈ یا پروموشنل پوسٹ کو گریڈینٹ سے وہ توانائی ملتی ہے جو فلیٹ رنگ نہیں دے سکتا۔</p>\n<p>جب سامنے والی تصویر تفصیل دار ہو تو گریڈینٹ ہلکا رکھیں۔ مصروف پروڈکٹ فوٹو تیز گریڈینٹ پر توجہ کے لیے لڑتی ہے، اور پروڈکٹ ہار جاتی ہے۔ گریڈینٹ کو پس منظر رہنے دیں۔</p>\n<h2 id=\"blurred-photo-backgrounds\">دھندلی تصویر والے پس منظر</h2>\n<p>Blurred Photo موڈ پہلو کے تناسب کا مسئلہ حل کرتا ہے۔ مربع کے طور پر پوسٹ کی گئی پورٹریٹ تصویر کے اطراف خالی پٹیاں چھوڑ دیتی ہے، اور اسٹوری کے طور پر پوسٹ کی گئی لینڈ اسکیپ بھی یہی کرتی ہے۔</p>\n<p>بلر ریڈیس کنٹرول طے کرتا ہے کہ پس منظر کتنا نرم ہو۔ ہلکا بلر اصل کی شکلیں نظر آنے دیتا ہے، جو سفر اور لائف اسٹائل تصاویر کے لیے موزوں ہے۔ بھاری بلر تقریباً رنگ کا دھبہ بنا دیتا ہے۔</p>\n<p>یہ موڈ دھندلے پس منظر پر ہلکا رنگ بھی ڈالتا ہے، جو تیز سامنے والی تصویر کو اس کی اپنی دھندلی کاپی سے الگ کھڑا ہونے میں مدد دیتا ہے۔ رنگ کے بغیر سامنے والی تصویر کے کنارے پس منظر میں گم ہو سکتے ہیں۔</p>\n<p>یہ موڈ صرف کٹ آؤٹ پر نہیں، کسی بھی تصویر پر کام کرتا ہے۔ اپنی پس منظر والی پوری تصویر کو بھی اس طرح فریم کیا جا سکتا ہے، جس میں دھندلی کاپی فریم کے ارد گرد بھرتی ہے۔</p>\n<h2 id=\"canvas-aspect-ratios\">کینوس کے پہلو کے تناسب</h2>\n<p>کینوس کا پہلو تناسب تصویر کی آخری شکل طے کرتا ہے۔ ٹول عام شکلوں کے لیے پری سیٹ دیتا ہے: فیڈ اور لسٹنگ کے لیے مربع، وائڈ اسکرین کے لیے 16:9، اور لمبی پوسٹس کے لیے 4:5۔</p>\n<p>مربع سب سے ورسٹائل شکل ہے۔ یہ فیڈ، لسٹنگ اور تھمب نیل میں کام کرتا ہے، اور ہر جگہ پیش گوئی کے مطابق کراپ ہوتا ہے۔ بیچ میں سامنے والی تصویر والا مربع کینوس ہمیشہ صاف لگتا ہے۔</p>\n<p>16:9 وائڈ اسکرین شکل بینر، ویڈیو تھمب نیل اور ویب سائٹ ہیڈر کے لیے موزوں ہے۔ چوڑے کینوس پر بیچ میں سامنے والی تصویر ہیرو تصویر لگتی ہے، جس میں متن کے لیے جگہ ہوتی ہے۔</p>\n<p>4:5 پورٹریٹ شکل سوشل فیڈ کے لیے موزوں ہے جو لمبی تصاویر کو انعام دیتی ہے، کیونکہ لمبی تصویر اسکرول کرتے ہوئے زیادہ اسکرین جگہ لیتی ہے۔ 4:5 کینوس پر پروڈکٹ زیادہ دیر نظر آتی ہے۔</p>\n<h2 id=\"image-scale-and-margins\">تصویر کا اسکیل اور حاشیے</h2>\n<p>Image Scale کنٹرول کرتا ہے کہ سامنے والی تصویر کینوس کے اندر کتنی بڑی نظر آئے۔ بڑا اسکیل فریم بھر دیتا ہے اور پروڈکٹ کو ہیرو بنا دیتا ہے۔ چھوٹا اسکیل ارد گرد سانس لینے کی جگہ چھوڑتا ہے۔</p>\n<p>حاشیے اہمیت رکھتے ہیں کیونکہ کنارے سے چپکی سامنے والی تصویر تنگ لگتی ہے، جبکہ پس منظر کے سمندر میں تیرتی تصویر کھوئی ہوئی لگتی ہے۔ درست اسکیل تصویر اور منزل پر منحصر ہوتا ہے۔</p>\n<p>جب کینوس کی شکل تصویر کی شکل سے مختلف ہو تو اسکیل ہی فریمنگ کا اوزار بن جاتا ہے۔ مربع کینوس پر لمبی تصویر کو فٹ ہونے کے لیے چھوٹے اسکیل کی ضرورت ہوتی ہے، جبکہ چوڑی تصویر کو بڑے اسکیل کی۔</p>\n<p>نتیجہ اس سائز پر چیک کریں جس پر اسے دیکھا جائے گا۔ دکان کی لسٹنگ میں تھمب نیل تصویر کو پورے سائز کے حصے پر دکھاتا ہے، اس لیے پورے سائز پر فراخ لگنے والے حاشیے چھوٹے میں خالی لگ سکتے ہیں۔</p>\n<h2 id=\"roundness-and-drop-shadow\">گولائی اور ڈراپ شیڈو</h2>\n<p>Roundness سامنے والی تصویر کے کونوں کو نرم کر دیتی ہے۔ مستطیل تصویر پر گول کونے کارڈ جیسا احساس دیتے ہیں جو سوشل پوسٹس اور ایپ اسکرین شاٹس کے لیے موزوں ہے۔</p>\n<p>ڈراپ شیڈو سامنے والی تصویر کو پس منظر سے اٹھا دیتا ہے۔ یہ گہرائی بڑھاتا ہے اور کٹ آؤٹ کو چپکایا ہوا نہیں بلکہ رکھا ہوا لگاتا ہے۔ یہ اثر شفاف لوگو کے ساتھ بہترین کام کرتا ہے۔</p>\n<p>ٹھوس مستطیل تصویر کے ساتھ ڈراپ شیڈو فریم شیڈو جیسا برتاؤ کرتا ہے: یہ موضوع کے بجائے مستطیل کی خاکہ بندی کرتا ہے۔ ہلکے پس منظر پر یہ ٹھیک لگ سکتا ہے۔</p>\n<p>دونوں کنٹرول جان بوجھ کر ہلکے رکھے گئے ہیں۔ بھاری شیڈو یا انتہائی کونے کا رداس تصویر کے بجائے اثر کی طرف توجہ کھینچتا ہے۔ گہرائی کے لیے اتنا استعمال کریں جتنا کافی ہو۔</p>\n<h2 id=\"output-formats-and-quality\">آؤٹ پٹ فارمیٹ اور کوالٹی</h2>\n<p>ٹول تیار تصویر کو JPG یا PNG کے طور پر ایکسپورٹ کرتا ہے۔ JPG تصاویر کے لیے اور ہر اس تصویر کے لیے درست انتخاب ہے جہاں چھوٹی فائل اہمیت رکھتی ہے، جیسے ویب سائٹ بینر یا سوشل پوسٹ۔</p>\n<p>PNG درست انتخاب ہے جب تصویر میں تیز متن اور فلیٹ رنگ ہوں جنہیں JPG دھندلا کر دے۔ PNG فائل بڑی ہوتی ہے، مگر یہ ہر کنارہ صاف رکھتی ہے۔ نیا پس منظر دونوں میں اچھا لگتا ہے۔</p>\n<p>JPG کے لیے ایکسپورٹ کوالٹی ڈیفالٹ طور پر زیادہ ہوتی ہے، جو سامنے والی تصویر کی تفصیل اور گریڈینٹ کی ہمواری محفوظ رکھتی ہے۔ کم کوالٹی پر ایکسپورٹ شدہ گریڈینٹ میں بینڈنگ نظر آ سکتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائل کا نام پس منظر کی سیٹنگ کو ظاہر کرتا ہے، تاکہ آپ کئی ورژن بناتے وقت ایکسپورٹس میں فرق پہچان سکیں۔ واضح فائل نام آپ کو غلط فائل کھولنے سے بچاتا ہے۔</p>\n<h2 id=\"backgrounds-for-product-photos\">پروڈکٹ فوٹو کے لیے پس منظر</h2>\n<p>پروڈکٹ فوٹو اپنے پس منظر سے بنتی یا بگڑتی ہے۔ صاف سفید پس منظر مارکیٹ پلیس کا معیار ہے کیونکہ یہ توجہ ہٹاتا ہے اور خریداروں کو مصنوعات کا موازنہ کرنے دیتا ہے۔</p>\n<p>رنگین پس منظر برانڈ اسٹور اور سوشل دکانوں کے لیے کام کرتے ہیں، جہاں تصویر لسٹنگ کے ساتھ ساتھ اشتہار بھی ہوتی ہے۔ تمام پروڈکٹ تصاویر پر ایک برانڈ رنگ دکان کو ایک جیسی پہچان دیتا ہے۔</p>\n<p>لائف اسٹائل سیاق و سباق تیسرا آپشن ہے، اور اس کا مطلب ہے پروڈکٹ کو فلیٹ رنگ کے بجائے منظر میں دکھانا۔ دھندلا تصویر والا پس منظر منظر کا اشارہ دے سکتا ہے بغیر توجہ ہٹائے۔</p>\n<p>جو بھی چنیں، پروڈکٹ رینج میں اسے مستقل رکھیں۔ جس دکان کی ہر لسٹنگ کا پس منظر مختلف ہو وہ غیر منظم لگتی ہے، جبکہ ایک پس منظر والی دکان پیشہ ورانہ لگتی ہے۔</p>\n<h2 id=\"backgrounds-for-social-media\">سوشل میڈیا کے لیے پس منظر</h2>\n<p>سوشل فیڈ ان تصاویر کو انعام دیتی ہے جو اسکرول روک دیں، اور پس منظر اس کام کا آدھا حصہ ہے۔ سادہ پس منظر سے زیادہ تیزی سے بولڈ گریڈینٹ یا مضبوط برانڈ رنگ آنکھ پکڑتا ہے۔</p>\n<p>کینوس کی شکل پلیٹفارم سے ملائیں۔ مربع فیڈ گرڈ کے لیے موزوں ہے، پورٹریٹ 4:5 اسکرولنگ فیڈ کے لیے، اور چوڑا 16:9 اسٹوری لنک یا ویڈیو تھمب نیل کے لیے۔</p>\n<p>پلیٹفارم انٹرفیس کے لیے جگہ چھوڑیں۔ کیپشن، بٹن اور پروفائل تصاویر زیادہ تر ایپس میں تصویر کے کناروں پر آ جاتی ہیں، اس لیے سامنے والی تصویر بیچ میں رکھیں اور کنارے خالی رکھیں۔</p>\n<p>پوسٹ کرنے سے پہلے تصویر اپنے فون پر آزمائیں۔ جو پس منظر ڈیسک ٹاپ مانیٹر پر ہلکا لگے وہ فون کی اسکرین پر تیز لگ سکتا ہے، اور جو گریڈینٹ ہموار لگے وہ فون پر بینڈ کر سکتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی وہ پس منظر ہے جو سامنے والی تصویر سے لڑتا ہے۔ تفصیل دار پروڈکٹ کے پیچھے تیز گریڈینٹ، یا پتلی لوگو کے پیچھے مصروف دھندلا پس منظر، دونوں کو نقصان پہنچاتا ہے۔</p>\n<p>دوسری غلطی ایکسپورٹ فارمیٹ بھول جانا ہے۔ نئے پس منظر پر شفاف کٹ آؤٹ کو JPG کے طور پر ایکسپورٹ کرنا ٹھیک ہے، کیونکہ پس منظر شفافیت کو بھر دیتا ہے۔</p>\n<p>تیسری غلطی آخری دیکھنے کے سائز کو نظر انداز کرنا ہے۔ پورے سائز پر فراخ لگنے والے حاشیے تھمب نیل میں خالی لگتے ہیں، اور متن جیسی تفصیل چھوٹے ہونے پر غائب ہو جاتی ہے۔</p>\n<p>آخر میں، بہت سے لوگ ایسی تصویر پر پس منظر لگا دیتے ہیں جس کا اصل گندا پس منظر ابھی موجود ہو۔ ٹول پوری تصویر کو نئے پس منظر پر رکھتا ہے، اس لیے پرانا پس منظر فریم کے اندر نظر آتا رہتا ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: پس منظر چننا</h2>\n<p>لسٹنگ، لوگو اور ہر اس چیز کے لیے ٹھوس رنگ استعمال کریں جہاں سامنے والی تصویر غالب رہنی چاہیے۔ سوشل گرافکس اور پروموشن کے لیے گریڈینٹ استعمال کریں جہاں توانائی مدد کرے۔ شکل کا مسئلہ حل کرنے کے لیے دھندلی تصویر والا پس منظر استعمال کریں۔</p>\n<p>کینوس کا تناسب منزل کے مطابق سیٹ کریں، سامنے والی تصویر کو سانس لینے کی جگہ کے ساتھ اسکیل کریں، اور تصاویر کے لیے JPG اور تیز متن کے لیے PNG ایکسپورٹ کریں۔ پیش نظارہ اس سائز پر دیکھیں جس پر آپ کے سامعین اسے دیکھیں گے۔</p>\n<p>مرحلہ بہ مرحلہ ورژن کے لیے <a href=\"/ur/blog/tasveer-par-background-kaise-lagayein/\">How to Add a Background to an Image</a> پڑھیں، اور پروڈکٹ سے متعلق مشورے کے لیے <a href=\"/ur/blog/product-photo-backgrounds/\">Product Photo Backgrounds: Colours and Context</a> دیکھیں۔ <a href=\"/ur/tasveer-par-background-lagayein/\">Add Background to Image</a> ٹول سے شروع کریں۔</p>\n";

